(()=>{'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],K=window.KCore,KEY='knowledge-atlas-v1',COLORS={'概念':'#111111','公式':'#111111','敘述':'#111111','實例':'#111111'},TYPES=['概念','敘述','公式','實例'];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data=K.validateData(window.SEED),loadError='',recovery='',storageOk=true;
try{let stored=localStorage.getItem(KEY);if(stored){try{data=K.validateData(JSON.parse(stored))}catch(e){recovery=stored;loadError='原有資料讀取失敗，已保留原始內容。請在資料管理下載後檢查：'+e.message}}else localStorage.setItem(KEY,K.serialize(data))}catch(e){storageOk=false;loadError='此瀏覽器無法使用本機儲存，修改只會留在本次頁面，請匯出備份。'}
let state={x:data.dimensions[0].id,y:data.dimensions[1].id,selected:null,tab:'overview',query:'',domains:[],types:[...TYPES],edges:true,zoom:1,panX:0,panY:0,cluster:null};
let pendingImport=null,toastTimer,graphSize={w:600,h:480},gesture=null,pointers=new Map(),suppressClick=false;
const uid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint32Array(4)),v=>v.toString(16).padStart(8,'0')).join('-');
const node=id=>data.nodes.find(n=>n.id===id),dim=id=>data.dimensions.find(d=>d.id===id),rtype=id=>data.relationTypes.find(r=>r.id===id),date=()=>new Date().toISOString();
function notify(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function storageStatus(){const warn=!storageOk||!!recovery;$('#saved').textContent=warn?'● 尚未持久保存':'● 本機已儲存';$('#saved').classList.toggle('storage-error',warn);$('#storageFoot').textContent=warn?'⚠ 請匯出備份；目前資料未安全保存':'儲存於此瀏覽器 · 建議定期匯出備份'}
function commit(next){next.updatedAt=date();const valid=K.validateData(next);if(recovery)throw new Error('請先到資料管理下載原始資料，並確認以目前資料取代損毀內容。');try{localStorage.setItem(KEY,K.serialize(valid));storageOk=true}catch(e){storageOk=false;notify('無法寫入本機；修改僅留在本頁，請立即匯出。')}data=valid;if(!dim(state.x))state.x=data.dimensions[0].id;if(!dim(state.y)||state.y===state.x)state.y=data.dimensions.find(d=>d.id!==state.x).id;if(state.selected&&!node(state.selected))state.selected=null;storageStatus();render();return true}
function filtered(){return K.filterNodes(data,state.query,state.domains,state.types)}
function grouping(){return K.groupNodes(filtered(),state.x,state.y)}
function score(n,id){return n.scores[id]?.value??null}
function shape(type){return type==='公式'?'square':type==='實例'?'diamond':''}
function dot(type){return `<i class="dot ${shape(type)}" style="--color:${COLORS[type]}"></i>`}
function nodeButton(n,subtitle=''){return `<button class="nodeitem" data-act="jump" data-id="${esc(n.id)}">${dot(n.type)}<div><strong>${esc(n.title)}</strong>${subtitle?`<small>${esc(subtitle)}</small>`:''}</div><span>↗</span></button>`}
function axisOptions(){for(const [el,key,other]of [['#xaxis','x','y'],['#yaxis','y','x']]){$(el).innerHTML=data.dimensions.map(d=>`<option value="${esc(d.id)}" ${state[key]===d.id?'selected':''} ${state[other]===d.id?'disabled':''}>${esc(d.name)}</option>`).join('')}}
function renderSidebar(){const domains=[...new Set(data.nodes.flatMap(n=>n.domains))];$('#domains').innerHTML=domains.map(d=>`<label class="domainrow"><input type="checkbox" data-domain="${esc(d)}" ${state.domains.includes(d)?'checked':''}><span>${esc(d)}</span><small>${data.nodes.filter(n=>n.domains.includes(d)).length}</small></label>`).join('');$('#types').innerHTML=TYPES.map(t=>`<button class="typechip ${state.types.includes(t)?'':'off'}" data-act="type" data-type="${t}" aria-pressed="${state.types.includes(t)}">${dot(t)}${t}</button>`).join('');$('#totalCount').textContent=data.nodes.length;$('#statNodes').textContent=data.nodes.length;$('#statRels').textContent=data.relations.length;$('#statDomains').textContent=domains.length;$('#pendingCount').textContent=K.groupNodes(data.nodes,state.x,state.y).pending.length}
function render(){axisOptions();renderSidebar();renderGraph();renderDetail();storageStatus()}
function transform(x,y){const{w,h}=graphSize,unit=Math.min((w-150)/5.2,(h-130)/5.2);return{x:w/2+(x-3)*unit*state.zoom+state.panX,y:h/2-(y-3)*unit*state.zoom+state.panY}}
function hideTooltip(){$('#tooltip').hidden=true}
function showTooltip(el){if(!el||pointers.size||state.cluster)return;const g=grouping().groups.find(g=>g.key===el.dataset.group);if(!g)return;const box=$('#tooltip'),p=transform(g.x,g.y),{w,h}=graphSize;box.innerHTML=`<div class="tip-meta">X ${esc(dim(state.x).name)} ${g.x} · Y ${esc(dim(state.y).name)} ${g.y}</div>${g.nodes.length===1?`<strong>${esc(g.nodes[0].title)}</strong><p>${esc(g.nodes[0].type)} · ${esc(g.nodes[0].definition)}</p>`:`<strong>${g.nodes.length} 個單元位於此座標</strong>${g.nodes.slice(0,6).map(n=>`<div class="tip-title">${esc(n.title)} · ${esc(n.type)}</div>`).join('')}${g.nodes.length>6?`<p>另有 ${g.nodes.length-6} 個單元</p>`:''}`}<div class="tip-action">${g.nodes.length>1?'點選展開全部單元':'點選查看完整內容'}</div>`;box.hidden=false;const bw=box.offsetWidth,bh=box.offsetHeight;box.style.left=Math.max(12,Math.min(w-bw-12,p.x+18))+'px';box.style.top=Math.max(12,Math.min(h-bh-12,p.y-bh/2))+'px'}
function renderGraph(){hideTooltip();const svg=$('#chart'),rect=$('#chartwrap').getBoundingClientRect();graphSize={w:Math.max(rect.width,280),h:rect.height||480};const{w,h}=graphSize;svg.setAttribute('viewBox',`0 0 ${w} ${h}`);const{groups,pending}=grouping(),selected=node(state.selected),selGroup=groups.find(g=>g.nodes.some(n=>n.id===state.selected)),origin=transform(3,3),margin=w<700?30:65;$('#visibleCount').textContent=`${filtered().length-pending.length} 個單元 · ${groups.length} 個座標位置`;$('#pendingLink').textContent=`待評分 ${K.groupNodes(data.nodes,state.x,state.y).pending.length} ↗`;$('#emptyMap').hidden=groups.length!==0;
 let html=`<defs><marker id="arrow" markerWidth="6" markerHeight="6" refX="5.5" refY="3" orient="auto"><path d="M0 0 L6 3 L0 6" fill="#999"/></marker><marker id="axisarrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M1 1 L7 4 L1 7" fill="none" stroke="#777" stroke-width="1"/></marker><clipPath id="plotclip"><rect x="10" y="10" width="${w-20}" height="${h-20}"/></clipPath></defs><rect width="${w}" height="${h}" fill="#fff"/>`;
 if(origin.y>25&&origin.y<h-25)html+=`<line class="x-axis" x1="${margin}" y1="${origin.y}" x2="${w-margin}" y2="${origin.y}" stroke="#aaa" stroke-width=".8" marker-end="url(#axisarrow)"/><text class="axis-label" x="${w-margin-6}" y="${origin.y-15}" text-anchor="end">X · ${esc(dim(state.x).name)}</text>`;
 if(origin.x>25&&origin.x<w-25)html+=`<line class="y-axis" x1="${origin.x}" y1="${h-margin}" x2="${origin.x}" y2="${margin}" stroke="#aaa" stroke-width=".8" marker-end="url(#axisarrow)"/><text class="axis-label" x="${origin.x+15}" y="${margin+7}">Y · ${esc(dim(state.y).name)}</text>`;
 for(let i=1;i<=5;i++){const p=transform(i,i);if(p.x>margin&&p.x<w-margin&&origin.y>25&&origin.y<h-25)html+=`<line x1="${p.x}" y1="${origin.y-3}" x2="${p.x}" y2="${origin.y+3}" stroke="#aaa" stroke-width=".8"/><text class="tick-label" x="${p.x+(i===3?-10:0)}" y="${origin.y+20}" text-anchor="middle">${i}</text>`;if(i!==3&&p.y>margin&&p.y<h-margin&&origin.x>25&&origin.x<w-25)html+=`<line x1="${origin.x-3}" y1="${p.y}" x2="${origin.x+3}" y2="${p.y}" stroke="#aaa" stroke-width=".8"/><text class="tick-label" x="${origin.x-13}" y="${p.y+3}" text-anchor="end">${i}</text>`}
 html+='<g clip-path="url(#plotclip)">';
 if(state.edges&&selected&&selGroup){const grouped=new Map();for(const r of data.relations.filter(r=>r.source===selected.id||r.target===selected.id)){const other=r.source===selected.id?r.target:r.source,g=groups.find(g=>g.nodes.some(n=>n.id===other));if(!g||g.key===selGroup.key)continue;const key=g.key+'|'+r.type+'|'+(r.source===selected.id?'out':'in');if(!grouped.has(key))grouped.set(key,{g,r,count:0});grouped.get(key).count++}let i=0;for(const{g,r,count}of grouped.values()){const a=transform(selGroup.x,selGroup.y),b=transform(g.x,g.y),out=r.source===selected.id,t=rtype(r.type),from=out?a:b,to=out?b:a,dx=to.x-from.x,dy=to.y-from.y,len=Math.hypot(dx,dy),sx=from.x+dx/len*9,sy=from.y+dy/len*9,ex=to.x-dx/len*12,ey=to.y-dy/len*12,offset=(i%3-1)*18;i++;const mx=(sx+ex)/2-dy/len*offset,my=(sy+ey)/2+dx/len*offset;html+=`<path d="M${sx},${sy} Q${mx},${my} ${ex},${ey}" fill="none" stroke="#bcbcbc" stroke-width=".8" ${t.directed?'marker-end="url(#arrow)"':'stroke-dasharray="3 5"'}/><text x="${(sx+2*mx+ex)/4}" y="${(sy+2*my+ey)/4-5}" text-anchor="middle" class="edgelabel">${esc(t.name)}${count>1?' ×'+count:''}</text>`}}
 for(const g of groups){const p=transform(g.x,g.y),isSelected=g.nodes.some(n=>n.id===state.selected);html+=`<g class="plotnode" tabindex="0" role="button" aria-label="${esc(`${dim(state.x).name} ${g.x}，${dim(state.y).name} ${g.y}，${g.nodes.length} 個單元：${g.nodes.map(n=>n.title).join('、')}`)}" data-group="${g.key}" transform="translate(${p.x},${p.y})"><circle r="22" fill="transparent"/><circle class="point-focus" r="11" fill="none" stroke="#ccc" stroke-width=".8"/>${isSelected?'<path d="M-9 0H-6M6 0H9M0-9V-6M0 6V9" stroke="#111" stroke-width="1"/>':''}<circle class="point" r="3.5" fill="#111"/></g>`}
 html+='</g>';svg.innerHTML=html;$('#legend').textContent='圖上統一以黑點呈現；類型可於提示、清單與詳情查看。';renderCluster();}
function renderCluster(){const box=$('#cluster');if(!state.cluster){box.hidden=true;return}const g=grouping().groups.find(g=>g.key===state.cluster);if(!g){box.hidden=true;state.cluster=null;return}box.hidden=false;box.innerHTML=`<div class="clusterhead"><h3>此位置的 ${g.nodes.length} 個單元</h3><button data-act="close-cluster" aria-label="關閉重疊節點清單">×</button></div><p class="clusterhint">${esc(dim(state.x).name)} ${g.x} · ${esc(dim(state.y).name)} ${g.y}<br>選取任一單元；原始評分與座標保持不變。</p>${g.nodes.map(n=>nodeButton(n,n.id+' · '+n.type)).join('')}`}
function relatedList(n,kind){return data.relations.filter(r=>r.type==='part'&&(kind==='children'?r.source===n.id:r.target===n.id)).map(r=>nodeButton(node(kind==='children'?r.target:r.source)))}
function renderDetail(){const n=node(state.selected),box=$('#detail');box.hidden=!n;if(!n){box.innerHTML='';return}
 box.innerHTML=`<div class="detailtop"><div class="detailmeta"><span>${n.id===data.coreId?'✦ 主題核心':'知識單元'}</span><span class="right">${esc(n.id)}</span><button class="iconbutton" data-act="close-detail" aria-label="關閉單元詳情">×</button></div><span class="badge">${dot(n.type)}${n.type}</span> <span class="badge ${n.status==='待查證'?'pending':''}">${esc(n.status)}</span><h2>${esc(n.title)}</h2><p>${esc(n.definition)}</p><div class="detailactions"><span class="badge">X ${score(n,state.x)??'—'}　Y ${score(n,state.y)??'—'}</span><button class="smallbutton" data-act="edit" data-id="${esc(n.id)}">✎ 編輯單元</button></div></div><div class="detailtabs">${[['overview','概覽'],['scores','評分'],['relations','連結'],['sources','來源']].map(([id,label])=>`<button class="${state.tab===id?'active':''}" data-act="tab" data-tab="${id}">${label}</button>`).join('')}</div><div class="detailbody">${detailContent(n)}</div>`;
}
function detailContent(n){if(state.tab==='scores')return `<div class="notice">每個評分都是可修訂的知識描述；核心相關與應用直接性固定參照半導體擴散製程。</div>${data.dimensions.map(d=>`<div class="scorerow"><h3>${esc(d.name)} <strong>${score(n,d.id)??'待評分'}${score(n,d.id)?'<small> / 5</small>':''}</strong></h3><p>${esc(n.scores[d.id]?.reason||'尚未填寫理由。')}</p><p class="symbols">${score(n,d.id)?esc(d.rules[score(n,d.id)-1]):'此欄保留空值，不使用 0 分替代。'}</p></div>`).join('')}<button class="button primary" data-act="edit" data-id="${esc(n.id)}">修改評分與理由</button> <button class="textbutton" data-act="rules">查看完整評分表 ↗</button>`;
 if(state.tab==='sources')return `<div class="sectiontitle">可核對的參考資料</div>${n.status==='待查證'?'<div class="notice warning">此單元尚未完成查證，請補上材料系統、適用條件與可靠來源。</div>':''}${n.sources.length?n.sources.map(s=>`<div class="sourcecard"><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a><p>${esc(s.note)}</p><small>${s.checkedAt?'查核日期 '+esc(s.checkedAt):'未記錄查核日期'}</small></div>`).join(''):'<div class="list-empty">尚未附上參考來源。</div>'}<p class="symbols">內容以繁體中文重新整理。計算實例為明示假設下的自行計算，評分與連結理由為可修訂的編輯判斷。</p>`;
 if(state.tab==='relations'){const rs=data.relations.filter(r=>r.source===n.id||r.target===n.id);return `<div class="sectiontitle">從這裡繼續探索 <button class="textbutton" data-act="relation" data-id="${esc(n.id)}">＋ 建立關係</button></div><div class="notice">箭頭依定義表示方向。共同原理、共同數學形式與類比各自記錄；同座標的連結也列於下方。</div>${rs.length?rs.map(r=>{const t=rtype(r.type),out=r.source===n.id,other=node(out?r.target:r.source);return `<div class="relationship"><div class="relcaption">${esc(t.name)} · ${r.type==='part'?(out?'向內：子單元 ↓':'向上：父單元 ↑'):t.directed?(out?'此單元 → 對方':'對方 → 此單元'):'雙向關聯'}<button class="delete-rel" data-act="remove-rel" data-id="${esc(r.id)}">移除</button></div>${nodeButton(other,other.id)}<p>${esc(r.reason)}</p></div>`}).join(''):'<div class="list-empty">尚無關係，可建立第一條連結。</div>'}`}
 const children=relatedList(n,'children'),parents=relatedList(n,'parents'),otherCount=data.relations.filter(r=>r.type!=='part'&&(r.source===n.id||r.target===n.id)).length;
 return `<div class="sectiontitle">領域標籤</div><div class="tags">${n.domains.map(d=>`<span class="tag">${esc(d)}</span>`).join('')}</div><div class="sectiontitle">知識筆記</div><p>${esc(n.detail||'尚無詳細說明。')}</p>${n.formula?`<div class="sectiontitle">公式</div><div class="formula">${esc(n.formula)}</div><p class="symbols">${esc(n.symbols)}</p>`:''}${n.assumptions.length?`<div class="sectiontitle">條件與假設</div><ul class="assumptions">${n.assumptions.map(a=>`<li>${esc(a)}</li>`).join('')}</ul>`:''}<div class="sectiontitle">知識屬性 <button class="textbutton" data-act="tab" data-tab="scores">分數與理由 ↗</button></div><div class="scoresummary">${data.dimensions.map(d=>`<div class="miniscore"><span>${esc(d.name)}</span><div class="minibar">${[1,2,3,4,5].map(i=>`<i class="${score(n,d.id)>=i?'filled':''}"></i>`).join('')}</div><b>${score(n,d.id)??'—'}</b></div>`).join('')}</div><div class="sectiontitle">向上 · 父單元</div>${parents.length?parents.join(''):'<div class="list-empty">目前沒有父單元。</div>'}<div class="sectiontitle" style="margin-top:20px">向內 · 子單元 <span>${children.length}</span></div>${children.length?children.join(''):'<div class="list-empty">此單元還可以繼續拆解。</div>'}<button class="textbutton" data-act="child" data-id="${esc(n.id)}">＋ 新增子單元</button><div class="sectiontitle" style="margin-top:22px">向外 · 應用與其他連結</div><button class="nodeitem" data-act="tab" data-tab="relations"><div>查看 ${otherCount} 條其他連結<small>先備、應用、共同原理與跨領域類比</small></div><span>↗</span></button><button class="textbutton" data-act="relation" data-id="${esc(n.id)}">連結既有單元，避免重複建立 ↗</button>`;
}
function selectNode(id){if(!node(id))return;state.selected=id;state.tab='overview';state.cluster=null;const visible=filtered().some(n=>n.id===id);if(!visible){state.query='';state.domains=[];state.types=[...TYPES];$('#search').value='';notify('已清除篩選，顯示所選單元。')}state.zoom=1;state.panX=state.panY=0;toggleSidebar(false);render();$('#detail').scrollTop=0;$('#detail [data-act="close-detail"]')?.focus({preventScroll:true})}
function modal(title,subtitle,body,foot=''){const el=$('#modal');$('#modalContent').innerHTML=`<div class="modalhead"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div><button class="closebutton" data-act="close-modal" aria-label="關閉視窗">×</button></div>${body}${foot?`<div class="modalfoot">${foot}</div>`:''}`;if(!el.open)el.showModal()}
function closeModal(){$('#modal').close();pendingImport=null}
function field(label,name,value='',extra='',tag='input'){return `<label class="field ${extra.includes('data-full')?'full':''}"><span>${label}</span>${tag==='textarea'?`<textarea name="${name}" ${extra}>${esc(value)}</textarea>`:`<input name="${name}" value="${esc(value)}" ${extra}>`}</label>`}
function openEditor(id,parentId){const old=id?node(id):null,n=old||{id:'KN-'+uid(),title:'',type:'概念',definition:'',detail:'',formula:'',symbols:'',domains:[],assumptions:[],sources:[],scores:{},status:'待查證'};
 modal(old?'編輯知識單元':parentId?'新增子單元':'新增知識單元',`穩定 ID：${n.id}`,`<form id="editor" data-id="${esc(n.id)}" data-parent="${esc(parentId||'')}" data-existing="${!!old}"><div class="modalbody"><div class="formgrid">${field('標題 *','title',n.title,'required maxlength="160" data-full')}<label class="field"><span>節點類型</span><select name="type">${TYPES.map(t=>`<option ${n.type===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field"><span>查證狀態</span><select name="status">${['待查證','已核對','使用者筆記'].map(t=>`<option ${n.status===t?'selected':''}>${t}</option>`).join('')}</select></label>${field('簡短定義 *','definition',n.definition,'required data-full','textarea')}${field('詳細說明','detail',n.detail,'data-full','textarea')}${field('公式（可使用 Unicode 數學符號）','formula',n.formula,'data-full placeholder="例如：J = −D ∂C/∂x"','textarea')}${field('符號與單位說明','symbols',n.symbols,'data-full','textarea')}${field('條件假設（每行一項）','assumptions',n.assumptions.join('\n'),'data-full','textarea')}${field('領域標籤（以逗號或頓號分隔）','domains',n.domains.join('、'),'data-full')}</div><h3 class="formsection">各維度評分與理由</h3><div class="notice">可保留「未評分」。每個已填分數都需附理由；分數不代表價值高低。</div>${data.dimensions.map(d=>`<div class="scoreedit"><span>${esc(d.name)}<br><small>${esc(d.reference)}</small></span><select name="score_${esc(d.id)}" aria-label="${esc(d.name)}分數"><option value="">未評分</option>${[1,2,3,4,5].map(v=>`<option value="${v}" ${n.scores[d.id]?.value===v?'selected':''}>${v} 分</option>`).join('')}</select><input name="reason_${esc(d.id)}" aria-label="${esc(d.name)}評分理由" placeholder="一句簡短理由" value="${esc(n.scores[d.id]?.reason||'')}" maxlength="1000"></div>`).join('')}<h3 class="formsection">參考來源</h3><label class="field"><span>每行：標題 | 網址 | 查核位置或備註</span><textarea name="sources" placeholder="來源標題 | https://… | 章節、頁碼或備註">${esc(n.sources.map(s=>[s.title,s.url,s.note].join(' | ')).join('\n'))}</textarea><small>「已核對」需至少一個來源。尚未確認的資料請標記待查證。</small></label><div class="error" id="formError" role="alert"></div></div><div class="modalfoot"><button type="button" class="button" data-act="close-modal">取消</button><button type="submit" class="button primary">儲存單元</button></div></form>`);
 $('#editor').addEventListener('submit',e=>{e.preventDefault();try{const f=new FormData(e.currentTarget),scores={};for(const d of data.dimensions){const raw=f.get('score_'+d.id),reason=f.get('reason_'+d.id).trim();if(raw&&!reason)throw new Error(`請填寫「${d.name}」的評分理由。`);scores[d.id]={value:raw?Number(raw):null,reason}}const sources=f.get('sources').split('\n').map(x=>x.trim()).filter(Boolean).map(line=>{const parts=line.split('|').map(s=>s.trim());if(parts.length<2)throw new Error('來源格式：標題 | https://網址 | 備註');const prior=old?.sources.find(s=>s.url===parts[1]&&s.title===parts[0]&&s.note===parts.slice(2).join(' | '));return {title:parts[0],url:parts[1],note:parts.slice(2).join(' | '),checkedAt:prior?.checkedAt||(f.get('status')==='已核對'?date().slice(0,10):null)}});if(f.get('status')==='已核對'&&!sources.length)throw new Error('標記已核對前，請至少提供一項可核對來源。');const updated={...n,title:f.get('title').trim(),type:f.get('type'),status:f.get('status'),definition:f.get('definition').trim(),detail:f.get('detail').trim(),formula:f.get('formula').trim(),symbols:f.get('symbols').trim(),domains:[...new Set(f.get('domains').split(/[,，、]/).map(x=>x.trim()).filter(Boolean))],assumptions:f.get('assumptions').split('\n').map(x=>x.trim()).filter(Boolean),sources,scores,createdAt:n.createdAt||date(),updatedAt:date()},next=K.clone(data);if(old)next.nodes[next.nodes.findIndex(x=>x.id===n.id)]=updated;else next.nodes.push(updated);if(parentId)next.relations.push({id:'KR-'+uid(),source:parentId,target:n.id,type:'part',reason:'從父主題拆解出的獨立知識單元。'});commit(next);state.selected=n.id;state.tab='overview';state.cluster=null;closeModal();render();notify(storageOk?'知識單元已儲存。':'已更新本頁；請匯出以免遺失。')}catch(err){$('#formError').textContent=err.message;$('#formError').scrollIntoView({block:'nearest'})}})
}
function openRules(){modal('共用評分表與維度','1–5 分是可修訂的描述，並非客觀量測或知識排名。',`<div class="modalbody"><div class="notice">「與核心相關程度」與「製程應用直接性」固定以半導體擴散製程為參照。2、4 分有獨立判準，不以模糊中間值處理。新增維度會將現有單元的該分數保留為空值。</div>${data.dimensions.map(d=>`<section class="ruledim"><h3>${esc(d.name)} <button class="textbutton" data-act="dimension" data-id="${esc(d.id)}">編輯定義</button></h3><p>${esc(d.reference)}</p><table class="ruletable"><tbody>${d.rules.map((r,i)=>`<tr><th>${i+1} 分</th><td>${esc(r)}</td></tr>`).join('')}</tbody></table></section>`).join('')}</div>`,`<button class="button" data-act="dimension">＋ 新增維度</button><button class="button primary" data-act="close-modal">完成</button>`)}
function openDimension(id){const old=id?dim(id):null;modal(old?'編輯維度定義':'新增評分維度','所有單元共用同一套規則；變更後請檢查既有評分是否仍適用。',`<form id="dimensionForm"><div class="modalbody"><div class="formgrid">${field('維度名稱 *','name',old?.name||'','required')}${field('評分參照 *','reference',old?.reference||'知識單元本身',`required ${['relevance','application'].includes(id)?'readonly':''}`)}${[1,2,3,4,5].map(v=>field(v+' 分判準 *','rule'+v,old?.rules[v-1]||'','required data-full')).join('')}</div><div class="error" id="formError"></div></div><div class="modalfoot"><button type="button" class="button" data-act="rules">返回評分表</button><button class="button primary" type="submit">儲存維度</button></div></form>`);$('#dimensionForm').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.currentTarget),name=f.get('name').trim();if(data.dimensions.some(d=>d.name===name&&d.id!==id))throw new Error('已有相同名稱的維度。');const d={id:id||'dim-'+uid(),name,short:name,reference:f.get('reference').trim(),rules:[1,2,3,4,5].map(v=>f.get('rule'+v).trim())},next=K.clone(data);if(old)next.dimensions[next.dimensions.findIndex(x=>x.id===id)]=d;else{next.dimensions.push(d);next.nodes.forEach(n=>n.scores[d.id]={value:null,reason:''})}commit(next);openRules();notify('維度定義已儲存。')}catch(err){$('#formError').textContent=err.message}}}
function openRelation(id){const selected=id||state.selected;modal('建立知識關係','共用既有節點，分開記錄組成、先備與跨領域連結。',`<form id="relationForm"><div class="modalbody"><div class="formgrid"><label class="field full"><span>關係類型</span><select name="type" id="relationType">${data.relationTypes.map(t=>`<option value="${esc(t.id)}">${esc(t.name)} ${t.directed?'→':'↔'}</option>`).join('')}</select></label><p class="relation-help full" id="relationHelp"></p><label class="field"><span>來源／父單元／先備</span><select name="source">${data.nodes.map(n=>`<option value="${esc(n.id)}" ${n.id===selected?'selected':''}>${esc(n.title)} · ${esc(n.id)}</option>`).join('')}</select></label><label class="field"><span>目標／子單元／應用</span><select name="target"><option value="">選擇另一個既有單元</option>${data.nodes.map(n=>`<option value="${esc(n.id)}">${esc(n.title)} · ${esc(n.id)}</option>`).join('')}</select></label>${field('連結理由 *','reason','','required data-full placeholder="說明共用原理、數學形式、應用方式或類比的限制。"','textarea')}</div><div class="error" id="formError" role="alert"></div></div><div class="modalfoot"><button type="button" class="button" data-act="close-modal">取消</button><button class="button primary" type="submit">建立關係</button></div></form>`);const help=()=>$('#relationHelp').textContent=rtype($('#relationType').value).description;help();$('#relationType').onchange=help;$('#relationForm').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.currentTarget);if(!f.get('target'))throw new Error('請選擇目標單元。');const next=K.clone(data);next.relations.push({id:'KR-'+uid(),source:f.get('source'),target:f.get('target'),type:f.get('type'),reason:f.get('reason').trim()});commit(next);state.tab='relations';closeModal();render();notify('關係已建立。')}catch(err){$('#formError').textContent=err.message}}}
function openList(pendingOnly=false){const list=pendingOnly?K.groupNodes(data.nodes,state.x,state.y).pending:filtered();modal(pendingOnly?'待評分單元':'所有知識單元',pendingOnly?`缺少 ${dim(state.x).name} 或 ${dim(state.y).name}：${list.length} 個（不受篩選影響）`:`符合目前搜尋與篩選：${list.length} 個`, `<div class="modalbody">${pendingOnly?'<div class="notice">未評分保留為 null，補上兩軸分數後就會回到圖中。點選查看詳情，或直接補分。</div>':''}${list.length?`<div class="modal-list">${list.map(n=>`<div>${nodeButton(n,`${n.id} · X ${score(n,state.x)??'未評分'} / Y ${score(n,state.y)??'未評分'}`)}${pendingOnly?`<button class="textbutton" data-act="edit" data-id="${esc(n.id)}">補上評分 →</button>`:''}</div>`).join('')}</div>`:'<div class="list-empty">目前沒有符合條件的單元。</div>'}</div>`)}
function download(text,name){const url=URL.createObjectURL(new Blob([text],{type:'application/json;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportData(){download(K.serialize(data),'knowledge-atlas-'+date().slice(0,10)+'.json');notify('已匯出完整 JSON 備份。')}
function openBackup(){modal('資料管理','完整備份節點、關係、維度、評分規則與來源。',`<div class="modalbody">${loadError?`<div class="notice warning">${esc(loadError)}${recovery?'<br><button class="textbutton" data-act="recover-download">下載原始資料</button> · <button class="textbutton" data-act="recover-reset">確認以目前資料繼續</button>':''}</div>`:''}<div class="notice">資料保存在目前瀏覽器與網站網址下，不會自動跨裝置同步。清除網站資料會刪除本機內容，請先匯出。</div><div class="backupgrid"><section class="backupcard"><h3>匯出知識圖譜</h3><p>${data.nodes.length} 個單元 · ${data.relations.length} 條關係<br>${data.dimensions.length} 個維度 · schema v1</p><button data-act="export" class="button primary">↓ 下載完整 JSON</button><button data-act="show-json" class="textbutton">顯示 JSON 以便複製</button></section><section class="backupcard"><h3>匯入 JSON 備份</h3><p>先檢查格式與關係，再預覽取代內容。匯入會取代目前資料，建議先匯出備份。</p><input id="importFile" type="file" accept=".json,application/json" aria-label="選擇匯入 JSON 檔案"><textarea id="importText" class="jsonarea" placeholder="也可以直接貼上完整 JSON" aria-label="貼上匯入 JSON"></textarea><button class="button" data-act="validate-import">檢查匯入內容</button><div id="importError" class="error" role="alert"></div></section></div><div id="exportArea"></div></div>`);$('#importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024){$('#importError').textContent='檔案超過 10 MB，請縮小資料集。';return}try{previewImport(await file.text())}catch(err){$('#importError').textContent=err.message}}}
function previewImport(text){try{if(text.length>10*1024*1024)throw new Error('資料超過 10 MB。');const checked=K.validateData(JSON.parse(text));pendingImport=checked;modal('確認匯入資料','驗證通過；尚未變更目前資料。',`<div class="modalbody"><div class="notice warning">這會取代目前 ${data.nodes.length} 個單元與 ${data.relations.length} 條關係。若要保留目前內容，請先下載備份。</div><p>匯入：<b>${checked.nodes.length}</b> 個單元 · <b>${checked.relations.length}</b> 條關係 · <b>${checked.dimensions.length}</b> 個維度</p><p class="relation-help">已檢查 ID、分數範圍、維度規則、關係端點、重複關係及父子循環。</p><div class="error" id="importError"></div></div>`,`<button class="button" data-act="export">先下載目前備份</button><button class="button" data-act="backup">取消</button><button class="button primary" data-act="confirm-import">取代並匯入</button>`)}catch(e){$('#importError').textContent='匯入失敗，原資料未變更：'+e.message}}
function help(){modal('操作說明','',`<div class="modalbody"><ol class="help-list"><li><b>從左上角開啟選項。</b>選擇兩個不同維度作為 X／Y 軸，也可搜尋、篩選、查看評分表及新增單元。</li><li><b>軸線交會於 (3, 3)。</b>原始分數維持 1–5，從左到右、從下到上遞增；中心不代表 0 分。位置接近只代表當前兩軸評分接近。</li><li><b>移到點上查看提示。</b>每個黑點是一個已評分座標。多個單元重疊時，提示會顯示數量與名稱，點選即可展開完整清單。觸控直接點選；鍵盤可聚焦點並按 Enter。</li><li><b>點選後查看完整內容。</b>詳情保留類型、父子單元、公式、評分與來源；「連結」列出方向和理由。關閉詳情即回到單純的座標畫面。</li><li><b>移動與縮放。</b>滑鼠拖曳、滾輪、觸控單指拖曳或雙指縮放皆可操作；選項內提供縮放與重設視角。</li><li><b>編輯、補分與備份。</b>每個已填分數需有理由。缺少目前任一軸分數的單元可在待評分清單補分。修改立即保存於本機，資料管理可匯出／匯入完整 JSON。</li></ol></div>`)}
function toggleSidebar(open){const panel=$('#sidebar'),value=open??!panel.classList.contains('visible');panel.classList.toggle('visible',value);panel.inert=!value;$('#menuToggle').classList.toggle('is-open',value);$('#menuToggle').setAttribute('aria-expanded',String(value));hideTooltip();if(value)$('#sidebar [data-act="close-sidebar"]').focus({preventScroll:true});else $('#menuToggle').focus({preventScroll:true})}
function closeDetail(){const selected=node(state.selected);state.selected=null;renderDetail();renderGraph();if(selected){const el=[...$('#chart').querySelectorAll('[data-group]')].find(el=>{const g=grouping().groups.find(g=>g.key===el.dataset.group);return g?.nodes.some(n=>n.id===selected.id)});el?.focus({preventScroll:true});hideTooltip()}}
function zoom(factor){state.zoom=Math.max(.65,Math.min(3,state.zoom*factor));state.cluster=null;renderGraph()}
const actions={map:()=>{closeModal();state.cluster=null;renderGraph()},filters:()=>toggleSidebar(),'close-sidebar':()=>toggleSidebar(false),'close-detail':closeDetail,list:()=>openList(),pending:()=>openList(true),help,rules:openRules,dimension:b=>openDimension(b.dataset.id),new:()=>openEditor(),edit:b=>openEditor(b.dataset.id),child:b=>openEditor(null,b.dataset.id),relation:b=>openRelation(b.dataset.id),backup:()=>{pendingImport=null;openBackup()},export:exportData,'show-json':()=>{$('#exportArea').innerHTML=`<label class="field" style="margin-top:20px"><span>完整 JSON（可全選複製）</span><textarea class="jsonarea" readonly aria-label="完整 JSON 匯出內容">${esc(K.serialize(data))}</textarea></label>`},'validate-import':()=>previewImport($('#importText').value),'confirm-import':()=>{if(!pendingImport)return;try{const imported=K.clone(pendingImport);commit(imported);state.x=data.dimensions[0].id;state.y=data.dimensions[1].id;state.selected=null;state.query='';state.domains=[];state.types=[...TYPES];state.cluster=null;state.tab='overview';state.zoom=1;state.panX=state.panY=0;$('#search').value='';closeModal();render();notify('完整資料已匯入。')}catch(e){$('#importError').textContent=e.message}},'close-modal':closeModal,'close-cluster':()=>{state.cluster=null;renderCluster()},jump:b=>{closeModal();selectNode(b.dataset.id)},tab:b=>{state.tab=b.dataset.tab;renderDetail()},clear:()=>{state.query='';state.domains=[];state.types=[...TYPES];$('#search').value='';state.cluster=null;render()},type:b=>{state.types=state.types.includes(b.dataset.type)?state.types.filter(t=>t!==b.dataset.type):[...state.types,b.dataset.type];state.cluster=null;render()},swap:()=>{[state.x,state.y]=[state.y,state.x];state.cluster=null;state.zoom=1;state.panX=state.panY=0;render()},'zoom-in':()=>zoom(1.2),'zoom-out':()=>zoom(1/1.2),reset:()=>{state.zoom=1;state.panX=state.panY=0;state.cluster=null;renderGraph()},'remove-rel':b=>{const r=data.relations.find(r=>r.id===b.dataset.id);modal('移除這條關係',`${node(r.source).title} → ${node(r.target).title}`,`<div class="modalbody"><p>${esc(rtype(r.type).name)}：${esc(r.reason)}</p><p class="relation-help">僅移除關係，兩個知識單元都會保留。</p></div>`,`<button class="button" data-act="close-modal">取消</button><button class="button danger" data-act="confirm-remove-rel" data-id="${esc(r.id)}">移除關係</button>`)},'confirm-remove-rel':b=>{const next=K.clone(data);next.relations=next.relations.filter(r=>r.id!==b.dataset.id);commit(next);closeModal();notify('關係已移除。')},'recover-download':()=>download(recovery,'knowledge-atlas-recovery.json'),'recover-reset':()=>{recovery='';loadError='';commit(data);openBackup()}};
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(b){e.preventDefault();try{actions[b.dataset.act]?.(b)}catch(err){notify(err.message)}}});
$('#search').addEventListener('input',e=>{state.query=e.target.value;state.cluster=null;renderGraph();renderDetail()});$('#domains').addEventListener('change',e=>{const d=e.target.dataset.domain;if(!d)return;state.domains=e.target.checked?[...state.domains,d]:state.domains.filter(x=>x!==d);state.cluster=null;renderGraph()});
for(const [el,axis,other]of [['#xaxis','x','y'],['#yaxis','y','x']])$(el).onchange=e=>{if(e.target.value===state[other])return;state[axis]=e.target.value;state.cluster=null;state.zoom=1;state.panX=state.panY=0;render()};
$('#showEdges').onchange=e=>{state.edges=e.target.checked;renderGraph()};
function openGroup(key){hideTooltip();const g=grouping().groups.find(g=>g.key===key);if(!g)return;if(g.nodes.length===1)selectNode(g.nodes[0].id);else{state.cluster=key;renderCluster();$('#cluster button')?.focus()}}
$('#chart').addEventListener('click',e=>{if(suppressClick){suppressClick=false;return}const g=e.target.closest('[data-group]');if(g)openGroup(g.dataset.group);else{state.cluster=null;renderCluster()}});$('#chart').onkeydown=e=>{const g=e.target.closest('[data-group]');if(g&&(e.key==='Enter'||e.key===' ')){e.preventDefault();openGroup(g.dataset.group)}};
$('#chart').addEventListener('pointerover',e=>{if(e.pointerType!=='touch')showTooltip(e.target.closest('[data-group]'))});
$('#chart').addEventListener('pointerout',e=>{const g=e.target.closest('[data-group]');if(g&&!g.contains(e.relatedTarget))hideTooltip()});
$('#chart').addEventListener('focusin',e=>showTooltip(e.target.closest('[data-group]')));
$('#chart').addEventListener('focusout',hideTooltip);
$('#chart').addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY>0?1/1.12:1.12)},{passive:false});
function beginGesture(){const ps=[...pointers.values()];if(ps.length===2){gesture={kind:'pinch',distance:Math.hypot(ps[0].x-ps[1].x,ps[0].y-ps[1].y),zoom:state.zoom,cx:(ps[0].x+ps[1].x)/2,cy:(ps[0].y+ps[1].y)/2,panX:state.panX,panY:state.panY};suppressClick=true}else if(ps.length===1)gesture={kind:'pan',x:ps[0].x,y:ps[0].y,panX:state.panX,panY:state.panY};else gesture=null}
$('#chart').onpointerdown=e=>{hideTooltip();pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(!e.target.closest('[data-group]'))$('#chart').setPointerCapture(e.pointerId);suppressClick=false;beginGesture()};
$('#chart').onpointermove=e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(!gesture)return;const ps=[...pointers.values()];if(gesture.kind==='pinch'&&ps.length===2){const dist=Math.hypot(ps[0].x-ps[1].x,ps[0].y-ps[1].y);state.zoom=Math.max(.65,Math.min(3,gesture.zoom*dist/Math.max(gesture.distance,1)));state.panX=gesture.panX+(ps[0].x+ps[1].x)/2-gesture.cx;state.panY=gesture.panY+(ps[0].y+ps[1].y)/2-gesture.cy;suppressClick=true}else if(gesture.kind==='pan'){const dx=e.clientX-gesture.x,dy=e.clientY-gesture.y;if(Math.hypot(dx,dy)<5&&!suppressClick)return;state.panX=gesture.panX+dx;state.panY=gesture.panY+dy;suppressClick=true}$('#chart').setPointerCapture(e.pointerId);state.cluster=null;renderGraph()};
for(const event of ['pointerup','pointercancel'])window.addEventListener(event,e=>{pointers.delete(e.pointerId);beginGesture()});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#modal').open){hideTooltip();if(state.cluster){state.cluster=null;renderCluster()}else if($('#sidebar').classList.contains('visible'))toggleSidebar(false);else if(state.selected)closeDetail()}});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue)notify('其他分頁已更新資料；請重新整理以載入最新版本。')});
new ResizeObserver(()=>renderGraph()).observe($('#chartwrap'));render();if(loadError)setTimeout(()=>{notify(loadError);openBackup()},300);
})();
